select date_format(store_sales.sale_date, 'yyyy-MM') sale_month, store_sales.store_id, sum(inventory.quantity) total_quantity, max(inventory.quantity) - min(inventory.quantity) quantity_range from inventory inner join store_sales on inventory.store_id = store_sales.store_id and inventory.product_id = store_sales.product_id group by date_format(store_sales.sale_date, 'yyyy-MM'), store_sales.store_id order by total_quantity desc
